import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline
import os
import sys

# Monkey-patch the reference model to fix the broadcasting error
try:
    import reference
    def fixed_apply_rotary_pos_emb(q, k, cos, sin, position_ids=None, unsqueeze_dim=1):
        # The original code used unsqueeze_dim=1 which caused [q_len, 1, head_dim]
        # We need [1, 1, q_len, head_dim] to broadcast with [bsz, num_heads, q_len, head_dim]
