    const float* __restrict__ input,
    const float* __restrict__ weight,
    float* __restrict__ output,
    float eps,
    int hidden_size,
    int num_elements
) {
    int row_idx = blockIdx.x;
    const float* row_input = input + row_idx * hidden_size;
    float* row_output = output + row_idx * hidden_size;

    float sum_sq = 0.0f;
    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        float val = row_input[i];
        sum_sq += val * val;
    }

    // Block reduce sum
    __shared__ float shared_sum_sq[256];
    int tid = threadIdx.x;
    shared_sum_sq[tid] = sum_sq;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_sum_sq[tid] += shared_sum_sq[tid + s];
        }
        __syncthreads();
    }

    float inv_rms = rsqrtf(shared_sum_sq[0] / hidden_size + eps);

    for (int i = threadIdx.x; i < hidden_size; i += blockDim.x) {
        row_output[i] = row_input[i] * inv_rms * weight[i];
    }
}

torch::Tensor rms_norm_hip(torch::Tensor input, torch::Tensor weight, float eps) {
    int hidden_size = input.size(-1);
    int num_rows = input.numel() / hidden_size;
    auto output = torch::empty_like(input);

    const int block_size = 256;
    rms_norm_kernel<<<num_rows, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        eps,
        hidden_size,
        input.numel()
    );

    return output;
}

// Fused kernel for RoPE application and concatenation
// This will handle both Query and Key
// q_nope: [bsz, q_len, num_heads, nope_dim]
// q_pe: [bsz, q_len, num_heads, rope_dim]
// k_pe: [bsz, q_len, 1, rope_dim]
// cos, sin: [q_len, rope_dim]
// out_q: [bsz, num_heads, q_len, nope_dim + rope_dim]
// out_k: [bsz, num_heads, q_len, nope_dim + rope_dim]

__global__ void rope_and_concat_kernel(
    const float* __restrict__ q_nope,
    const float* __restrict__ q_pe,
    const float* __restrict__ k_nope,
    const float* __restrict__ k_pe_in,
    const float* __restrict__ cos,
    const float* __restrict__ sin,
    float* __restrict__ out_q,
    float* __restrict__ out_k,
    int bsz, int q_len, int num_heads, int nope_dim, int rope_dim
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int head_dim = nope_dim + rope_dim;
    int total_elements_q = bsz * q_len * num_heads * head_dim;

    if (idx < total_elements_q) {
        // q_nope/q_pe indexing: [bsz][q_len][num_heads][dim]
        // out_q/out_k indexing: [bsz][num_heads][q_len][head_dim]

        int d = idx % head_dim;
        int h = (idx / head_dim) % num_heads;
        int s = (idx / (head_dim * num_heads)) % q_len;
        int b = idx / (head_dim * num_heads * q_len);

        int out_idx = ((b * num_heads + h) * q_len + s) * head_dim + d;

        if (d < nope_dim) {
            // Nope component
            int in_idx = ((b * q_len + s) * num_heads + h) * nope_dim + d;
            out_q[out_idx] = q_nope[in_idx];

            int in_k_idx = ((b * q_len + s) * num_heads + h) * nope_dim + d;
            out_k[out_idx] = k_nope[in_k_idx];
        } else {
            // RoPE component
            int rd = d - nope_dim;
            int half_rope = rope_dim / 2;
            int in_idx = ((b * q_len + s) * num_heads + h) * rope_dim + rd;

            // k_pe_in: [bsz, q_len, 1, rope_dim]
            int in_k_pe_idx = ((b * q_len + s) * 1 + 0) * rope_dim + rd;

            float q_val = q_pe[in_idx];
            float k_val = k_pe_in[in_k_pe_idx];

            float c = cos[s * rope_dim + rd];
            float s_val = sin[s * rope_dim + rd];

            // RoPE rotation: (q * cos) + (rotate_half(q) * sin)
            // rotate_half(x) = [-x2, x1]
            float q_rotated, k_rotated;
            if (rd < half_rope) {
                float q_other = q_pe[in_idx + half_rope];
                float k_other = k_pe_in[in_k_pe_idx + half_rope];
                q_rotated = q_val * c - q_other * s_val;
                k_rotated = k_val * c - k_other * s_val;
            } else {
                float q_other = q_pe[in_idx - half_rope];
                float k_other = k_pe_in[in_k_pe_idx - half_rope];
                q_rotated = q_val * c + q_other * s_val;
                k_rotated = k_val * c + k_other * s_val;
            }
            out_q[out_idx] = q_rotated;
            out_k[out_idx] = k_rotated;
        }
    }
}

std::vector<torch::Tensor> rope_and_concat_hip(
    torch::Tensor q_nope, torch::Tensor q_pe,
    torch::Tensor k_nope, torch::Tensor k_pe,
    torch::Tensor cos, torch::Tensor sin
) {
    int bsz = q_nope.size(0);
    int q_len = q_nope.size(1);
    int num_heads = q_nope.size(2);
    int nope_dim = q_nope.size(3);
    int rope_dim = q_pe.size(3);
    int head_dim = nope_dim + rope_dim;

    auto out_q = torch::empty({bsz, num_heads, q_len, head_dim}, q_nope.options());
    auto out_k = torch::empty({bsz, num_heads, q_len, head_dim}, q_nope.options());

    int total_elements = bsz * q_len * num_heads * head_dim;
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    rope_and_concat_kernel<<<num_blocks, block_size>>>(
        q_nope.data_ptr<float>(),
        q_pe.data_ptr<float>(),
        k_nope.data_ptr<float>(),
        k_pe.data_ptr<float>(),
        cos.data_ptr<float>(),
        sin.data_ptr<float>(),
        out_q.data_ptr<float>(),
        out_k.data_ptr<float>(),
        bsz, q_len, num_heads, nope_dim, rope_dim
    );

    return {out_q, out_k};
}
